from collections import deque
import sys

def shortest_path(graph, source, target):
    # Initialize distance and path
    distance = float("inf")
    path = None

    # Queue for the BFS
    queue = deque([(source, [source]))  # node, path taken so far
    visited = set()

    while queue:
        current, current_path = queue.popleft()

        if current == target:
            # If we reached the target, check if it's a shorter path than the current distance
            if len(current_path) < distance:
                distance, path = len(current_path), current_path[:]
            elif len(current_path) == distance and current_path < path:
                distance, path = len(current_path), current_path[:]
            continue

        if current in visited:
            continue

        visited.add(current)

        for neighbour, weight in graph.get(current, []):
            if neighbour not in visited:
                queue.append((neighbour, current_path + [neighbour]))

    return (distance, path) if path else (float("inf"), None)

